// Low-level port I/O read (1 byte)

unsigned short port_addr = 0x3F8; // Example: Serial Data Port
unsigned char data_byte;

// NOTE: Requires prior ioperm() or iopl() setup
// e.g., ioperm(port_addr, 1, 1);

data_byte = inb(port_addr);

// Opposite: outb(value, port_addr);
// Related Reads: inw() (2 bytes), inl() (4 bytes)
